import software.amazon.awssdk.services.sqs.SqsClient;
import software.amazon.awssdk.services.sqs.model.*;
import java.io.*;
import java.nio.file.*;
import java.util.zip.*;
import java.util.Base64;

public class ArtifactProcessorWorker {

    private static final String QUEUE_URL = System.getenv("SQS_QUEUE_URL");
    private static final String EXTRACT_DIR = "/opt/artifacts/extracted";
    private final SqsClient sqsClient;

    public ArtifactProcessorWorker() {
        this.sqsClient = SqsClient.builder().build();
    }

    public void pollAndProcess() {
        while (true) {
            ReceiveMessageRequest req = ReceiveMessageRequest.builder()
                .queueUrl(QUEUE_URL)
                .maxNumberOfMessages(5)
                .waitTimeSeconds(20)
                .build();

            for (Message msg : sqsClient.receiveMessage(req).messages()) {
                try {
                    processMessage(msg);
                    sqsClient.deleteMessage(DeleteMessageRequest.builder()
                        .queueUrl(QUEUE_URL)
                        .receiptHandle(msg.receiptHandle())
                        .build());
                } catch (Exception e) {
                    System.err.println("Error processing message: " + e.getMessage());
                }
            }
        }
    }

    private void processMessage(Message msg) throws IOException {
        // Message body contains base64-encoded zip artifact
        byte[] zipBytes = Base64.getDecoder().decode(msg.body());
        extractZipArtifact(zipBytes);
    }

    /**
     * Extracts zip artifact to the configured extraction directory.
     * Files are extracted preserving internal directory structure for
     * downstream pipeline consumption.
     */
    private void extractZipArtifact(byte[] zipData) throws IOException {
        File destDir = new File(EXTRACT_DIR);
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        try (ZipInputStream zis = new ZipInputStream(new ByteArrayInputStream(zipData))) {
            ZipEntry entry;
            while ((entry = zis.getNextEntry()) != null) {
                // Construct target path from entry name
                String entryName = entry.getName();
                File targetFile = new File(destDir, entryName);

                // Create parent directories if needed
                if (entry.isDirectory()) {
                    targetFile.mkdirs();
                    continue;
                }

                targetFile.getParentFile().mkdirs();

                // Write file contents
                try (FileOutputStream fos = new FileOutputStream(targetFile)) {
                    byte[] buffer = new byte[4096];
                    int len;
                    while ((len = zis.read(buffer)) > 0) {
                        fos.write(buffer, 0, len);
                    }
                }

                // Set reasonable permissions
                targetFile.setReadable(true, false);
                targetFile.setWritable(false, false);
                targetFile.setExecutable(false, false);

                System.out.println("Extracted: " + targetFile.getAbsolutePath());
                zis.closeEntry();
            }
        }
    }

    /**
     * Validates message format before processing.
     * Checks base64 encoding validity and zip magic bytes.
     */
    private boolean isValidZipPayload(String body) {
        try {
            byte[] decoded = Base64.getDecoder().decode(body);
            return decoded.length >= 4 &&
                   decoded[0] == 0x50 && decoded[1] == 0x4B &&
                   decoded[2] == 0x03 && decoded[3] == 0x04;
        } catch (IllegalArgumentException e) {
            return false;
        }
    }

    public static void main(String[] args) {
        ArtifactProcessorWorker worker = new ArtifactProcessorWorker();
        System.out.println("Starting artifact processor worker...");
        System.out.println("Extract directory: " + EXTRACT_DIR);
        worker.pollAndProcess();
    }
}
